const gridData = await browserjs(tabId, () => {
  // Let's find the grid or table
  const table = document.querySelector('[role="grid"]') || document.querySelector('table');
  if (!table) return "No table/grid found";

  // Get headers
  const headers = Array.from(table.querySelectorAll('[role="columnheader"], th')).map(h => h.innerText.trim());

  // Get rows
  const rows = Array.from(table.querySelectorAll('[role="row"], tr')).map(row => {
    const cells = Array.from(row.querySelectorAll('[role="gridcell"], [role="rowheader"], td, th')).map(c => {
      return {
        text: c.innerText.trim(),
        ariaLabel: c.getAttribute('aria-label'),
        title: c.getAttribute('title'),
        classes: c.className
      };
    });
    return cells;
  });

  return { headers, rows };
});

