    result.push({
      idx,
      text: r.innerText.trim().replace(/\n+/g, ' | '),
      html: r.innerHTML
    });
  });

  // Also let's inspect any elements with class containing 'cell' or availability numbers
  const cells = Array.from(document.querySelectorAll('[data-testid*="cell"], [class*="cell"]')).map(c => ({
    text: c.innerText.trim(),
    ariaLabel: c.getAttribute('aria-label'),
    title: c.getAttribute('title'),
    className: c.className
  }));

  return { rowsCount: rows.length, rows: result, cellsSnippet: cells.slice(0, 30) };
});

console.log("Rows count:", details.rowsCount);
details.rows.forEach(r => {
  console.log(`Row ${r.idx}: ${r.text}`);
});

